#!/usr/bin/env python3
"""Generate self-contained static county pages and all254 inventory, no network."""
import collections,csv,gzip,html,io,json,re
from pathlib import Path
from acquire import ROOT,sha,save_json
from build_geometry import VINTAGES
H=html.escape
STYLE='''body{font:16px/1.55 system-ui,sans-serif;color:#182f40;background:#f4f7fa;margin:0}main{max-width:1180px;margin:auto;padding:32px}a{color:#125b88}h1{font-size:34px;line-height:1.2}h2{margin-top:32px}p{max-width:1000px}.notice{border-left:5px solid #b77a20;background:#fff4dd;padding:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:18px}.card{padding:20px;background:white;border:1px solid #ced8df;border-radius:8px}img{max-width:100%;height:auto;border:1px solid #d7dee4}table{border-collapse:collapse;width:100%;background:white;font-size:14px}th,td{text-align:left;padding:8px;border-bottom:1px solid #dae1e7}th{background:#dce9ef;position:sticky;top:0}.scroll{overflow:auto}code{font-size:13px;word-break:break-all}details{padding:10px;background:#fff;border:1px solid #dae1e7;margin:10px 0}summary{cursor:pointer;font-weight:600}input{font:inherit;padding:10px;width:min(94%,450px)}small{color:#526878}.badge{display:inline-block;background:#dce9ef;padding:2px 9px;border-radius:8px;font-size:13px}.warn{color:#7d4713}.download{padding:8px 0}footer{margin-top:40px;border-top:1px solid #cbd7df;padding-top:15px;font-size:14px}ul{padding-left:24px}'''
def page(title,body):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+H(title)+'</title><style>'+STYLE+'</style><main>'+body+'<footer>Texas Senate research • Offline original-byte archive and reference boundaries • No vote allocation or approved reporting crosswalk</footer></main></html>'
def link(path,label):return '<a href="'+H(path,quote=True)+'">'+H(str(label))+'</a>'
def write_csv(p,rows):
 with p.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)

def main():
 data=ROOT.parent/'data';counties=list(csv.DictReader((data/'county-turnout.csv').open()));priority=(data/'coordinator-priority-keys.txt').read_text().splitlines();notes=json.loads((ROOT/'county-notes.json').read_text());geom=json.loads((ROOT/'geometry/summary.json').read_text());compat=json.loads((ROOT/'inventory/compatibility-summary.json').read_text());pdf=json.loads((ROOT/'pdf/inspection.json').read_text())['sources'];sources=[json.loads(p.read_text()) for p in sorted((ROOT/'sources').glob('*.json'))]
 bysource={s['id']:s for s in sources};pdfby={p['source_id']:p for p in pdf};lg=json.loads((ROOT/'geometry/local-summary.json').read_text())['layers']
 canonical={c['county'].casefold():c['county'] for c in counties}
 notes={canonical[k.casefold()]:v for k,v in notes.items()}
 discoveries=[json.loads(p.read_text()) for p in (ROOT/'discovery').glob('*.json')];disby=collections.defaultdict(list)
 for d in discoveries:disby[canonical[d['county'].casefold()]]+=d['routes']
 # Bind follow-route PDF metadata to the published county identity, not its filename.
 owner={r['source_id']:d['county'] for d in discoveries for r in d['routes']}
 for s in sources:
  if s.get('id') in owner:s['county']=owner[s['id']]
  if s.get('county'):s['county']=canonical[s['county'].casefold()]
 dirs=json.loads((data/'results-sources/county-discovery.json').read_text());dirby={r['county_fips']:r for r in dirs};assert len(dirby)==254
 inventory=[];manifest=[];cards=[];allrows=[];documentlinks=[]
 (ROOT/'pages').mkdir(exist_ok=True)
 for c in counties:
  fips=c['county_fips'];name=c['county'];deep=c['dispatch_key'] in priority;gg=geom['counties'][fips];status=compat['by_county'].get(fips,{})
  cs=[s for s in sources if s.get('county')==name];cps=[s for s in cs if s['id'] in pdfby];clg=[a for a in lg if a['county']==name]
  row=dict(rank=c['rank'],county=name,county_fips=fips,dispatch_key=c['dispatch_key'],priority80=int(deep),senate_2024_total=c['senate_2024_total'],official_election_url=dirby[fips].get('official_directory_url',''),tlc_24g_features=gg['24g']['features'],tlc_26p_features=gg['26p']['features'],tlc_22g_features=gg['22g']['features'],tlc_20g_features=gg['20g']['features'],local_GIS_layers=len(clg),local_GIS_features=sum(a['features'] for a in clg),local_PDF_originals=len(cps),source_native_reporting_identities=sum(status.values()),compatibility_status_counts=json.dumps(status,separators=(',',':')),scope='Four countywide native precinct reference vintages; deep local inspection' if deep else 'Four statewide native precinct references; local deep investigation outside priority scope',current_November_boundary_approval='not established',county_note=notes.get(name,'Nonpriority county retained in statewide/native reporting inventory; no deep local acquisition claimed.'))
  inventory.append(row)
  countyurl='pages/'+fips+'.html' if deep else '#all-counties'
  allrows.append('<tr data-county="'+H(name.lower())+'"><td>'+c['rank']+'</td><td>'+link(countyurl,name)+('</td><td>')+fips+'</td><td>'+('priority' if deep else 'reference')+'</td>'+''.join('<td>'+str(gg[v]['features'])+'</td>' for v in VINTAGES)+'<td>'+str(sum(status.values()))+'</td></tr>')
  if not deep:continue
  body=link('../index.html','← Texas offline index')+'<h1>'+H(name)+' County</h1><p><span class="badge">Priority '+c['rank']+' of34</span> <code>'+fips+'</code> • '+format(int(c['senate_2024_total']),',')+' accepted2024 Senate candidate votes</p><p class="notice">'+H(notes[name])+'</p>'
  body+='<h2>Complete county reference boundaries</h2><p>Each ZIP copies every source SHP geometry body and DBF record verbatim. Only SHP/SHX headers, record numbering and county bounds are rebuilt. All attributes, rings and vertices remain; no simplification, topology repair or vote allocation. Native CRS: NAD83 Texas Lambert Conformal Conic, metre, X=easting/Y=northing.</p><div class="grid">'
  for v,label in VINTAGES.items():
   a=json.loads((ROOT/'geometry'/('tlc-'+v+'-audit.json')).read_text());ca=next(x for x in a['counties'] if x['county_fips']==fips);ss=bysource['tlc-'+v]
   body+='<div class="card"><h3>'+H(label)+'</h3><p>'+str(ca['features'])+' precinct features • '+format(ca['vertices'],',')+' source vertices</p>'
   if ca.get('preview'):body+=link('../'+ca['preview'],'Open full preview')+'<img src="../'+ca['preview']+'" alt="'+H(name+' '+label+' reference precinct boundaries')+'" loading="lazy">'
   body+='<p class="download">'+link('../'+ca['subset']['path'],'Download full-resolution county shapefile ZIP')+'</p><p>'+link('../sources/tlc-'+v+'.json','Original HTTP provenance and byte-part reconstruction')+' • '+link('../geometry/tlc-'+v+'-audit.json','Complete geometry/ID audit')+'</p><small>Reference vintage: '+H(label)+'. November2026 approval unknown.</small></div>'
   manifest.append(dict(asset_id=fips+'-'+v,county=name,county_fips=fips,kind='lossless county subset',source_id='tlc-'+v,source_url=ss['requested_url'],parent_url=ss.get('parent_source_url'),vintage=label,CRS='NAD83 Texas Lambert Conformal Conic metre; easting,northing',features=ca['features'],vertices=ca['vertices'],path=ca['subset']['path'],bytes=ca['subset']['bytes'],sha256=ca['subset']['sha256'],approval='November2026 unknown'))
  body+='</div><h2>Actual county originals</h2>'
  for s in cps:
   p=pdfby[s['id']];title=s.get('advertised_title') or s['id'];body+='<details><summary>'+H(title)+' • '+str(p['pages'])+' pages</summary><p>'+link('../sources/'+s['id']+'.json','HTTP provenance, original hash and reconstruction')+'</p><ul>'
   for j,x in enumerate(s['stored_parts']):body+='<li>'+link('../'+x['path'],('Original PDF' if s['storage_encoding']=='identity' and len(s['stored_parts'])==1 else 'Stored '+s['storage_encoding']+' bytes part '+str(j+1)))+' • '+str(x['bytes'])+' bytes</li>'
   body+='</ul><p>'+link(s['requested_url'],'Published source')+' • '+link('../'+p['text_path'],'Complete extracted source text (gzip)')+'</p>'
   for preview in p['preview_paths']:body+=link('../'+preview,preview.rsplit('/',1)[1])+'<br>'
   body+='<img src="../'+p['preview_paths'][0]+'" alt="'+H(title+' actual original page preview')+'" loading="lazy"><p><small>Selected page previews only; complete original has '+str(p['pages'])+' pages. Literal legal/date text is in pdf/inspection.json. Upload/retrieval dates do not establish current adoption.</small></p></details>'
   manifest.append(dict(asset_id=s['id'],county=name,county_fips=fips,kind='original PDF',source_id=s['id'],source_url=s['requested_url'],parent_url=s.get('parent_source_url'),vintage='see printed literal date/approval text; '+notes[name],CRS='PDF cartography; no geospatial CRS inferred',features='',vertices='',path='sources/'+s['id']+'.json',bytes=s['original_bytes'],sha256=s['original_sha256'],approval='source-specific printed evidence; no universal November2026 approval'))
  for a in clg:
   aa=json.loads((ROOT/a['source_audit']).read_text());body+='<details><summary>County GIS '+H(a['id'])+' • '+str(a['features'])+' features</summary><p>'+link('../'+a['source_audit'],'Complete pre/post IDs, counts and batch audit')+' • '+link('../geometry/gis-'+a['id']+'.json','Native CRS, invalid geometry, Z/M and overlap diagnostics')+'</p><p>Original full-precision query pages, all attributes; concatenate features using the audited IDs. No GeoJSON reprojection or curve linearization is used for originals.</p><ul>'
   for b in aa['batches']:
    ss=bysource[b['source_id']];body+='<li>'+link('../sources/'+ss['id']+'.json','Batch '+str(b['requested_ids'][0])+'…'+str(b['requested_ids'][-1])+' provenance')+': '+', '.join(link('../'+part['path'],'Original response '+str(j+1)) for j,part in enumerate(ss['stored_parts']))+'</li>'
   body+='</ul><img src="../'+a['preview']+'" alt="'+H(name+' county GIS reference')+'" loading="lazy"></details>'
   manifest.append(dict(asset_id=a['id'],county=name,county_fips=fips,kind='original GIS batch set',source_id=a['id'],source_url=aa['layer_url'],parent_url=aa['authority_parent'],vintage='source layer name/edit metadata; November approval unknown',CRS='see geometry/gis-'+a['id']+'.json',features=a['features'],vertices=a['vertices'],path=a['source_audit'],bytes='',sha256='',approval='unknown'))
  for zipkey in ['extra-harris-zip-https','extra-galveston-city-voting']:
   if zipkey not in bysource or bysource[zipkey].get('county')!=name:continue
   s=bysource[zipkey];a=json.loads((ROOT/'geometry'/(zipkey+'.json')).read_text())
   body+='<details><summary>Original shapefile ZIP • '+H(a['scope'])+' • '+str(a['features'])+' features</summary><p>'+link('../sources/'+zipkey+'.json','Original HTTP provenance')+' • '+link('../geometry/'+zipkey+'.json','Count, native attributes, vertices, CRS and geometry audit')+'</p><ul>'+''.join('<li>'+link('../'+part['path'],'Original ZIP bytes')+'</li>' for part in s['stored_parts'])+'</ul><img src="../'+a['preview']+'" alt="'+H(a['scope'])+'" loading="lazy"></details>'
   manifest.append(dict(asset_id=zipkey,county=name,county_fips=fips,kind='original shapefile ZIP',source_id=zipkey,source_url=s['requested_url'],parent_url=s.get('parent_source_url'),vintage=a['scope'],CRS='see geometry/'+zipkey+'.json',features=a['features'],vertices=sum(x['vertices'] for x in a['native_rows']),path='sources/'+zipkey+'.json',bytes=s['original_bytes'],sha256=s['original_sha256'],approval='reference scope only; November2026 unknown'))
  if not cps and not clg:body+='<p>Local native export remains a documented gap after the routes below. The four complete county reference ZIPs above are actual downloaded precinct geometry, independently labelled by vintage.</p>'
  body+='<h2>Source routes and precise access outcomes</h2><ul>'
  for r in disby[name]:body+='<li>'+link(r['url'],r['url'])+' — observed HTTP '+str(r.get('status'))+' • '+link('../sources/'+r['source_id']+'.json','retained response metadata')+'</li>'
  for s in cs:
   if s['id'].startswith('extra-') and s['id'] not in {r['source_id'] for r in disby[name]}:body+='<li>'+link(s['requested_url'],s.get('advertised_title') or s['id'])+' — HTTP '+str(s.get('status'))+' • '+link('../sources/'+s['id']+'.json','provenance')+'</li>'
  body+='</ul><h2>Native reporting compatibility</h2><p>'+str(sum(status.values()))+' source-scoped reporting identities accounted: '+H(json.dumps(status))+'. Exact literal ID overlap is ambiguous, not an approved crosswalk. Test/older election classes, vote centers and administrative groups remain separate.</p><p>'+link('../inventory/reporting-unit-compatibility.csv.gz','All identity-by-identity diagnostics')+' • '+link('../inventory/accepted-constituents.csv.gz','Full accepted constituent inventory')+'</p>'
  (ROOT/'pages'/(fips+'.html')).write_text(page(name+' precinct references',body))
  cards.append('<article class="card"><h2>'+link('pages/'+fips+'.html',c['rank']+'. '+name)+'</h2><p>'+str(gg['24g']['features'])+' precincts2024 • '+str(gg['26p']['features'])+' precincts2026 primary</p><a href="pages/'+fips+'.html"><img src="previews/'+fips+'-24g.png" alt="'+H(name+' native2024 precinct reference preview')+'" loading="lazy"></a><p>'+H(notes[name])+'</p></article>')
  for r in disby[name]:
   for l in r.get('links',[]):
    if re.search(r'precinct|vtd|vot.*map',l['label'],re.I):documentlinks.append(dict(county=name,county_fips=fips,parent=r['url'],label=l['label'],published_url=l['url'],route_source_id=r['source_id'],status='published link inventory; original acquisition must be checked independently, not all links are maps/current'))
 write_csv(ROOT/'inventory/all-counties.csv',inventory);write_csv(ROOT/'inventory/published-map-documents.csv',documentlinks);write_csv(ROOT/'manifest.csv',manifest)
 save_json(ROOT/'manifest.json',dict(scope='Originals stored once, lossless source subsets and separate raster previews; actual34 order maintained; all254 inventory.',sources=[dict(source_id=s['id'],metadata_path='sources/'+s['id']+'.json',county=s.get('county'),requested_url=s['requested_url'],status=s.get('status'),original_bytes=s.get('original_bytes'),original_sha256=s.get('original_sha256'),storage_encoding=s.get('storage_encoding'),stored_parts=s.get('stored_parts'),error=s.get('error')) for s in sources],map_assets=manifest))
 text='<h1>Texas precinct boundary archive</h1><p>34 priority counties • all254 counties inventoried • Four complete statewide native precinct vintages</p><p class="notice">Downloaded boundaries are reference assets.2026 primary geometry does not replace2024 general geometry. Native reporting identities, ballot styles, vote centers and precinct polygons remain distinct. No votes are spatially allocated; no approved November crosswalk or calibrated collector is claimed.</p><p>The accepted34 supply9,076,868 /11,291,854 reported2024 Senate candidate votes (80.384213%). Source-native geometry is retained in full; county downloads are byte-verified subsets, not county outlines.</p><p>'+link('../precinct-maps.md','Research and limitations')+' • '+link('SCHEMA.md','Schema/reproduction')+' • '+link('validation.json','Validation')+' • '+link('manifest.json','Provenance manifest')+' • '+link('asset-hashes.json','Saved asset hashes')+'</p><p>'+link('inventory/all-counties.csv','All254 county CSV')+' • '+link('inventory/reporting-unit-compatibility.csv.gz','48,637 reporting identity diagnostics')+' • '+link('inventory/native-geometry-units.csv.gz','All source-native statewide geometry IDs/attributes')+' • '+link('inventory/county-gis-units.csv.gz','County GIS native IDs/attributes')+' • '+link('inventory/accepted-constituents.csv.gz','45,944 accepted constituents')+'</p><h2>Priority counties in accepted order</h2><div class="grid">'+''.join(cards)+'</div><h2 id="all-counties">All254 counties</h2><p>Nonpriority counties retain all four statewide source references and observed native identities; local deep acquisition prioritizes the34. Entire statewide originals and reconstruction metadata: '+', '.join(link('sources/tlc-'+v+'.json',label) for v,label in VINTAGES.items())+'.</p><input id="filter" aria-label="Filter county table" placeholder="Filter counties by name"><div class="scroll"><table><thead><tr><th>Rank</th><th>County</th><th>FIPS</th><th>Scope</th><th>2024G</th><th>2026P</th><th>2022G</th><th>2020G</th><th>Observed reporting IDs</th></tr></thead><tbody>'+''.join(allrows)+'</tbody></table></div><script>document.getElementById("filter").addEventListener("input",function(){let q=this.value.toLowerCase();document.querySelectorAll("tr[data-county]").forEach(r=>r.hidden=!r.dataset.county.includes(q))})</script>'
 text=text.replace('48,637',format(compat['total_identities_accounted'],',')).replace('45,944',format(compat['accepted_constituents'],','))
 text=text.replace('all254','all 254').replace('of34','of 34').replace('the34','the 34')
 (ROOT/'index.html').write_text(page('Texas precinct boundary archive',text));print('index',len(inventory),'counties',len(cards),'priority pages',len(manifest),'map asset groups',flush=True)
if __name__=='__main__':main()
